tls_ctx* tls_ctx_create(void);
void tls_ctx_destroy(tls_ctx*);
const char* tls_eval(tls_ctx*, const char* input, int* out_len);
```
```go
// binding.go (conceptual)
// #include "tls.h"
// import "C"
import "runtime"
import "unsafe"
func Eval(input string) (string, error) {
  runtime.LockOSThread()
  defer runtime.UnlockOSThread()
  cstr := C.CString(input)
  defer C.free(unsafe.Pointer(cstr))
  var out C.int
  res := C.tls_eval(nil, cstr, &out)
  if res == nil {
    return "", fmt.Errorf("eval error")
  }
  return C.GoString(res), nil
}
